package schemas
import("testing";"strings")
func TestFactoryResponsesActualUnicodeDecoderProbe(t *testing.T){
 valid:=`{"id":"fixture","object":"response","status":"completed","usage":{"input_tokens":1,"output_tokens":2}}`
 for name,body:=range map[string]string{
 "status":strings.TrimSuffix(valid,"}")+`,"ſtatus":"incomplete"}`,
 "usage-root":strings.TrimSuffix(valid,"}")+`,"uſage":{"input_tokens":1000,"output_tokens":1000}}`,
 "usage-counter":strings.Replace(valid,`"input_tokens":1`,`"input_tokens":1,"input_tokenſ":1000`,1),
 }{t.Run(name,func(t *testing.T){
 var actual BifrostResponsesResponse
 if err:=actual.UnmarshalJSON([]byte(body));err!=nil{t.Fatal(err)}
 if actual.Status==nil || actual.Usage==nil{t.Fatal("actual schema missing canonical evidence")}
 usage,_,err:=factoryPhysicalUsage([]byte(body));if err!=nil{t.Fatal(err)}
 complete:=factoryPhysicalResponsesCompleted([]byte(body))
 t.Logf("actual_status=%q actual_input=%d actual_output=%d captured_input=%d captured_output=%d terminal=%v",*actual.Status,actual.Usage.InputTokens,actual.Usage.OutputTokens,usage["usage.input_tokens"],usage["usage.output_tokens"],complete)
 if complete && (*actual.Status!="completed" || int64(actual.Usage.InputTokens)!=usage["usage.input_tokens"] || int64(actual.Usage.OutputTokens)!=usage["usage.output_tokens"]){t.Fatal("capture disagrees with actual pinned decoder")}
 })}
}
